import limited_client as robot,numpy as np
from scipy.spatial.transform import Rotation as R
r=robot.observe()['robot'];q=np.array(r['joint_positions']);
for _ in range(6):robot.step(list(q)+[.002,.002])
r=robot.observe()['robot'];q0=np.array(r['joint_positions']);p0=np.array(r['tcp_position']);R0=R.from_quat(np.array(r['tcp_quaternion_wxyz'])[[1,2,3,0]])
DQ=[];DP=[];DW=[]
for i in range(7):
 t=q0.copy();t[i]+=.035
 for _ in range(5):robot.step(list(t)+[.002,.002])
 r=robot.observe()['robot'];qq=np.array(r['joint_positions']);pp=np.array(r['tcp_position']);RR=R.from_quat(np.array(r['tcp_quaternion_wxyz'])[[1,2,3,0]])
 DQ.append(qq-q0);DP.append(pp-p0);DW.append((RR*R0.inv()).as_rotvec());print('probe',i,'dq',np.round(qq-q0,3),'dp',np.round(pp-p0,4))
 for _ in range(6):robot.step(list(q0)+[.002,.002])
r=robot.observe()['robot'];DQ=np.array(DQ);DP=np.array(DP);DW=np.array(DW);Jp=np.linalg.lstsq(DQ,DP,rcond=None)[0].T;Jw=np.linalg.lstsq(DQ,DW,rcond=None)[0].T
print('base',p0.tolist(),q0.tolist());print('J',np.vstack((Jp,Jw)).tolist());print('restored',r['tcp_position'],r['joint_positions'],robot.status())
